INPUT  monic P of degree n, coefficients a_0, ..., a_{n-1}, a_n = 1
OUTPUT lambda > 0 and the normalised polynomial N_lambda(P)

1. C <- { |a_i|^(1/(n-i)) : i < n and a_i != 0 }
       // each root exists: the field is Euclidean with divisible ranks
2. if C is empty:            // P = z^n
3.     return lambda = 1, P
4. lambda <- max C           // exists: the order is total
5. for i = 0 .. n:
6.     b_i <- a_i * lambda^(i - n)
7. assert |b_i| <= 1 for all i          // valuation ring
8. assert exists i < n with |b_i| = 1   // residue polynomial != z^n
9. return lambda, (b_0, ..., b_n)

// every root z of a normalised monic polynomial satisfies |z| < 2:
//   |z|^n <= sum_{i<n} |z|^i = (|z|^n - 1)/(|z| - 1) <= |z|^n - 1
//   for |z| >= 2, a contradiction.
